[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellStream Platform — Integrated Energy Data Management</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<link rel="stylesheet" href="shared.css">
<style>
/* Hero */
.hero {
  min-height: 100vh;
  background: linear-gradient(135deg, #0D1B2A 0%, #15295A 50%, #0D1B2A 100%);
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding-top: 80px;
}
.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 70% 50%, rgba(108,194,74,0.08) 0%, transparent 60%),
              radial-gradient(ellipse at 30% 80%, rgba(0,180,216,0.06) 0%, transparent 50%);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  position: relative;
  z-index: 1;
}
.hero-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: #6CC24A;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}
.hero-title {
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 900;
  line-height: 1.1;
  color: #fff;
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
}
.hero-title span { color: #6CC24A; }
.hero-subtitle {
  font-size: 1.1rem;
  color: rgba(255,255,255,0.7);
  line-height: 1.7;
  margin-bottom: 2.5rem;
  max-width: 500px;
}
.hero-ctas { display: flex; gap: 1rem; flex-wrap: wrap; }
.hero-visual {
  display: flex;
  align-items: center;
  justify-content: center;
}
.platform-diagram {
  width: 100%;
  max-width: 520px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 16px;
  padding: 2rem;
  position: relative;
}
.diagram-title {
  text-align: center;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  color: #6CC24A;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
}
.diagram-pillars {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1rem;
  position: relative;
}
.diagram-pillars::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(108,194,74,0.4), rgba(0,180,216,0.4), transparent);
  transform: translateY(-50%);
}
.pillar {
  background: rgba(21,41,90,0.6);
  border: 1px solid rgba(108,194,74,0.25);
  border-radius: 12px;
  padding: 1.25rem 0.75rem;
  text-align: center;
  position: relative;
  z-index: 1;
  transition: all 0.3s ease;
}
.pillar:hover {
  border-color: #6CC24A;
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(108,194,74,0.15);
}
.pillar-icon {
  width: 44px; height: 44px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6CC24A22, #6CC24A44);
  border: 1px solid #6CC24A55;
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 0.75rem;
  font-size: 1.2rem;
}
.pillar-name {
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.4rem;
}
.pillar-sub {
  font-size: 0.65rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.4;
}
.diagram-center {
  margin-top: 1.5rem;
  text-align: center;
  padding: 1rem;
  background: linear-gradient(135deg, rgba(108,194,74,0.1), rgba(0,180,216,0.1));
  border: 1px solid rgba(108,194,74,0.3);
  border-radius: 12px;
}
.diagram-center-name {
  font-size: 1rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 0.25rem;
}
.diagram-center-sub { font-size: 0.75rem; color: rgba(255,255,255,0.6); }

/* Product Banner */
.product-banner {
  background: linear-gradient(90deg, #15295A 0%, #1a3575 50%, #0D1B2A 100%);
  border-top: 1px solid rgba(108,194,74,0.2);
  border-bottom: 1px solid rgba(108,194,74,0.2);
  padding: 1.5rem 0;
}
.banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
}
.banner-badge {
  background: #6CC24A;
  color: #0D1B2A;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  margin-bottom: 0.25rem;
  display: inline-block;
}
.banner-title {
  font-size: 1.4rem;
  font-weight: 800;
  color: #fff;
}
.banner-tagline { color: rgba(255,255,255,0.7); font-size: 0.9rem; }

/* Use Cases */
.use-cases { padding: 6rem 0; background: #0D1B2A; }
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-top: 3rem;
}
.use-case-card {
  background: rgba(21,41,90,0.4);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 14px;
  padding: 2rem 1.75rem;
  transition: all 0.3s ease;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}
.use-case-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 3px; height: 0;
  background: #6CC24A;
  transition: height 0.3s ease;
}
.use-case-card:hover {
  border-color: rgba(108,194,74,0.3);
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(0,0,0,0.3);
}
.use-case-card:hover::before { height: 100%; }
.uc-number {
  font-size: 0.7rem;
  font-weight: 700;
  color: #6CC24A;
  letter-spacing: 0.15em;
  margin-bottom: 0.75rem;
}
.uc-title {
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 0.75rem;
  line-height: 1.3;
}
.uc-desc { font-size: 0.85rem; color: rgba(255,255,255,0.6); line-height: 1.6; }
.uc-icon {
  width: 40px; height: 40px;
  border-radius: 10px;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.2);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
  margin-bottom: 1rem;
}

/* Industry Tabs */
.industry-section {
  padding: 6rem 0;
  background: linear-gradient(180deg, #0D1B2A 0%, #111E2E 100%);
}
.tabs-nav {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 2.5rem;
  margin-bottom: 2.5rem;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  padding-bottom: 0;
}
.tab-btn {
  background: none;
  border: none;
  color: rgba(255,255,255,0.5);
  font-size: 0.9rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: all 0.2s ease;
  font-family: 'Inter', sans-serif;
}
.tab-btn:hover { color: #fff; }
.tab-btn.active {
  color: #6CC24A;
  border-bottom-color: #6CC24A;
}
.tab-content { display: none; }
.tab-content.active { display: block; animation: fadeIn 0.3s ease; }
.industry-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}
.industry-text h3 {
  font-size: 1.75rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 1rem;
}
.industry-text p {
  color: rgba(255,255,255,0.7);
  line-height: 1.7;
  margin-bottom: 1.5rem;
}
.industry-features { list-style: none; display: flex; flex-direction: column; gap: 0.75rem; }
.industry-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  color: rgba(255,255,255,0.8);
  font-size: 0.9rem;
}
.industry-features li::before {
  content: '✓';
  color: #6CC24A;
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 0.1em;
}
.industry-visual {
  background: rgba(21,41,90,0.4);
  border: 1px solid rgba(108,194,74,0.2);
  border-radius: 16px;
  padding: 2.5rem;
  aspect-ratio: 4/3;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.industry-visual-content { text-align: center; }
.industry-visual-icon { font-size: 4rem; margin-bottom: 1rem; opacity: 0.8; }
.industry-visual-label { color: rgba(255,255,255,0.5); font-size: 0.85rem; }

/* Culture + Renewables */
.culture-section {
  padding: 6rem 0;
  background: #15295A;
  position: relative;
  overflow: hidden;
}
.culture-section::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px; height: 600px;
  background: radial-gradient(ellipse, rgba(108,194,74,0.08), transparent);
  border-radius: 50%;
}
.culture-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  position: relative;
  z-index: 1;
}
.culture-text h2 {
  font-size: 2.25rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 1.25rem;
  line-height: 1.2;
}
.culture-text p { color: rgba(255,255,255,0.7); line-height: 1.8; margin-bottom: 2rem; }
.culture-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.25rem;
}
.culture-stat {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 12px;
  padding: 1.25rem;
}
.culture-stat-value {
  font-size: 1.75rem;
  font-weight: 900;
  color: #6CC24A;
  margin-bottom: 0.25rem;
}
.culture-stat-label { font-size: 0.8rem; color: rgba(255,255,255,0.6); }

.renewables-cta-section {
  padding: 5rem 0;
  background: linear-gradient(135deg, #0a1520 0%, #0D1B2A 100%);
  border-top: 1px solid rgba(108,194,74,0.15);
}
.renewables-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2rem;
  align-items: center;
}
.renewables-text h2 {
  font-size: 1.75rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 0.75rem;
}
.renewables-text p { color: rgba(255,255,255,0.7); line-height: 1.7; max-width: 600px; }
.renewables-icons { display: flex; gap: 1rem; margin-top: 1rem; flex-wrap: wrap; }
.renewables-icon-chip {
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.25);
  border-radius: 20px;
  padding: 0.35rem 0.9rem;
  font-size: 0.78rem;
  color: #6CC24A;
  font-weight: 600;
}

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 1024px) {
  .hero-grid { grid-template-columns: 1fr; gap: 3rem; }
  .hero-visual { display: none; }
  .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
  .industry-content { grid-template-columns: 1fr; }
  .culture-grid { grid-template-columns: 1fr; }
  .renewables-inner { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .use-cases-grid { grid-template-columns: 1fr; }
  .tabs-nav { gap: 0; }
  .tab-btn { padding: 0.6rem 0.9rem; font-size: 0.8rem; }
  .culture-stats { grid-template-columns: 1fr 1fr; }
}
</style>
</head>
<body>

<!-- Navigation -->
<nav class="nav" id="mainNav">
  <div class="container nav-inner">
    <a href="index.html" class="nav-logo">
      <span class="logo-mark">W</span>
