</nav>

<!-- Hero -->
<section class="hero">
  <div class="container">
    <div class="hero-grid">
      <div class="hero-content">
        <div class="hero-label">Energy Data Management Platform</div>
        <h1 class="hero-title">Get Real-Time Data Across Your <span>Entire Operation</span></h1>
        <p class="hero-subtitle">The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.</p>
        <div class="hero-ctas">
          <a href="platform-overview.html" class="btn-primary btn-lg">Explore the Platform</a>
          <a href="request-demo.html" class="btn-outline btn-lg">Request A Demo</a>
        </div>
      </div>
      <div class="hero-visual">
        <div class="platform-diagram">
          <div class="diagram-title">WellStream Platform Ecosystem</div>
          <div class="diagram-pillars">
            <div class="pillar">
              <div class="pillar-icon">⛽</div>
              <div class="pillar-name">Well Data</div>
              <div class="pillar-sub">Lifecycle Management</div>
            </div>
            <div class="pillar">
              <div class="pillar-icon">📊</div>
              <div class="pillar-name">Production</div>
