              <div class="pillar-name">Land Data</div>
              <div class="pillar-sub">Management</div>
            </div>
          </div>
          <div class="diagram-center">
            <div class="diagram-center-name">WellStream Core Platform</div>
            <div class="diagram-center-sub">Plan · Drill · Complete · Manage · Optimize</div>
          </div>
          <div style="margin-top:1.25rem; display:grid; grid-template-columns:1fr 1fr; gap:0.75rem;">
            <div style="background:rgba(0,180,216,0.08);border:1px solid rgba(0,180,216,0.2);border-radius:8px;padding:0.75rem;text-align:center;">
              <div style="font-size:0.65rem;color:#00B4D8;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;">ETL Pipelines</div>
              <div style="font-size:0.6rem;color:rgba(255,255,255,0.5);margin-top:0.2rem;">Automated Data Flows</div>
            </div>
            <div style="background:rgba(0,180,216,0.08);border:1px solid rgba(0,180,216,0.2);border-radius:8px;padding:0.75rem;text-align:center;">
              <div style="font-size:0.65rem;color:#00B4D8;font-weight:700;text-transform:uppercase;letter-spacing:0.1em;">REST APIs</div>
              <div style="font-size:0.6rem;color:rgba(255,255,255,0.5);margin-top:0.2rem;">Real-Time Access</div>
            </div>
          </div>
        </div>
      </div>
    </div>
