</section>

<!-- Product Banner -->
<div class="product-banner">
  <div class="container">
    <div class="banner-inner">
      <div>
        <div class="banner-badge">Featured Product</div>
        <div class="banner-title">WellStream Innova</div>
        <div class="banner-tagline">Real-Time Directional Data Exchange — precision at every depth</div>
      </div>
      <a href="#" class="btn-outline">Learn More</a>
    </div>
  </div>
</div>

<!-- Use Cases -->
<section class="use-cases">
  <div class="container">
    <div class="section-label">USE CASES</div>
    <h2 class="section-title">See the WellStream Platform in Action</h2>
    <p class="section-desc" style="max-width:680px;">From drilling to production, land to water, watch how WellStream transforms every phase of your operations. Streamline workflows, unlock real-time insights, and make every decision count.</p>
    <div class="use-cases-grid">
      <div class="use-case-card">
        <div class="uc-icon">🛢️</div>
        <div class="uc-number">01</div>
        <div class="uc-title">Drilling &amp; Completions Management</div>
        <div class="uc-desc">Centralize drilling programs, daily reports, and well design data in one accessible hub.</div>
      </div>
      <div class="use-case-card">
        <div class="uc-icon">📈</div>
        <div class="uc-number">02</div>
        <div class="uc-title">Production Operations Oversight</div>
        <div class="uc-desc">Monitor production volumes, allocations, and decline curves with real-time dashboards.</div>
      </div>
      <div class="use-case-card">
        <div class="uc-icon">🔍</div>
        <div class="uc-number">03</div>
        <div class="uc-title">Asset Integrity Monitoring</div>
        <div class="uc-desc">Track well integrity risks, inspection schedules, and compliance status across your portfolio.</div>
      </div>
      <div class="use-case-card">
        <div class="uc-icon">💧</div>
        <div class="uc-number">04</div>
