      <a href="#" class="btn-outline">More Use Cases</a>
    </div>
  </div>
</section>

<!-- Industry Tabs -->
<section class="industry-section">
  <div class="container">
    <div class="section-label">Industries</div>
    <h2 class="section-title">Built for Every Segment of Energy</h2>
    <div class="tabs-nav" role="tablist">
      <button class="tab-btn active" role="tab" aria-selected="true" data-tab="ep">E&amp;P</button>
      <button class="tab-btn" role="tab" data-tab="midstream">Midstream</button>
      <button class="tab-btn" role="tab" data-tab="downstream">Downstream</button>
      <button class="tab-btn" role="tab" data-tab="utilities">Utilities</button>
      <button class="tab-btn" role="tab" data-tab="solar">Solar/Wind</button>
      <button class="tab-btn" role="tab" data-tab="mining">Mining</button>
    </div>
    <div class="tab-content active" data-panel="ep">
      <div class="industry-content">
        <div class="industry-text">
          <h3>Exploration &amp; Production</h3>
          <p>WellStream is purpose-built for E&amp;P operators managing complex well portfolios. Integrate drilling data, production volumes, and land obligations into a single, unified platform—from spud to abandonment.</p>
          <ul class="industry-features">
            <li>Centralize well lifecycle data from planning through P&amp;A</li>
            <li>Real-time drilling dashboards and daily report automation</li>
            <li>Production allocation and decline curve analytics</li>
            <li>Regulatory compliance tracking across multiple jurisdictions</li>
            <li>Mobile field data capture with offline sync capability</li>
          </ul>
        </div>
        <div class="industry-visual">
          <div class="industry-visual-content">
            <div class="industry-visual-icon">⛽</div>
            <div style="font-size:1rem;font-weight:700;color:#fff;margin-bottom:0.5rem;">E&amp;P Operations Hub</div>
            <div class="industry-visual-label">Well Data · Production · Land</div>
          </div>
        </div>
      </div>
    </div>
    <div class="tab-content" data-panel="midstream">
      <div class="industry-content">
        <div class="industry-text">
          <h3>Midstream Operations</h3>
          <p>Manage gathering systems, pipeline data, and facility operations with integrated tools that connect field measurement to financial reporting in real time.</p>
          <ul class="industry-features">
            <li>Pipeline throughput and allocation management</li>
            <li>Facility construction and commissioning workflows</li>
            <li>SCADA data integration and monitoring</li>
            <li>Volume reconciliation across custody transfer points</li>
          </ul>
        </div>
        <div class="industry-visual">
          <div class="industry-visual-content">
            <div class="industry-visual-icon">🔧</div>
            <div style="font-size:1rem;font-weight:700;color:#fff;margin-bottom:0.5rem;">Midstream Control Center</div>
            <div class="industry-visual-label">Pipelines · Facilities · Volumes</div>
          </div>
        </div>
      </div>
    </div>
    <div class="tab-content" data-panel="downstream">
      <div class="industry-content">
        <div class="industry-text">
