/* WellStream Platform — Shared Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0D1B2A;
  --navy-mid: #15295A;
  --navy-light: #1B2838;
  --green: #6CC24A;
  --green-dark: #52A334;
  --blue: #00B4D8;
  --blue-dark: #0077B6;
  --gray-dark: #3C424B;
  --text: #fff;
  --text-muted: rgba(255,255,255,0.65);
  --text-dim: rgba(255,255,255,0.45);
  --border: rgba(255,255,255,0.08);
  --border-green: rgba(108,194,74,0.25);
  --radius: 12px;
  --radius-sm: 8px;
  --radius-lg: 20px;
  --shadow: 0 4px 24px rgba(0,0,0,0.3);
  --shadow-lg: 0 12px 48px rgba(0,0,0,0.4);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, sans-serif;
  background: var(--navy);
  color: var(--text);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* Nav */
.nav {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  padding: 0;
  background: rgba(13,27,42,0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
  transition: all 0.3s ease;
}
.nav.scrolled {
  background: rgba(13,27,42,0.98);
  border-bottom-color: rgba(108,194,74,0.15);
}
.nav-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 2rem;
}
.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  text-decoration: none;
  flex-shrink: 0;
}
.logo-mark {
  width: 34px; height: 34px;
  background: linear-gradient(135deg, #6CC24A, #52A334);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
  font-weight: 900;
  color: #fff;
}
.logo-text {
  font-size: 1.1rem;
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.02em;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  flex: 1;
  margin-left: 1rem;
}
.nav-link {
  background: none;
  border: none;
  color: rgba(255,255,255,0.75);
  font-size: 0.9rem;
  font-weight: 500;
  padding: 0.5rem 0.85rem;
  border-radius: 8px;
  cursor: pointer;
  text-decoration: none;
  font-family: inherit;
  display: flex;
  align-items: center;
  gap: 0.35rem;
  transition: all var(--transition);
}
.nav-link:hover { color: #fff; background: rgba(255,255,255,0.06); }
.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
}

/* Dropdown */
.nav-dropdown { position: relative; }
.dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  min-width: 200px;
  background: #1a2a3a;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius);
  padding: 0.5rem;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all 0.2s ease;
  box-shadow: var(--shadow-lg);
}
.nav-dropdown:hover .dropdown-menu,
.nav-dropdown:focus-within .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.dropdown-item {
  display: block;
  padding: 0.6rem 0.875rem;
  color: rgba(255,255,255,0.75);
  text-decoration: none;
  font-size: 0.875rem;
  border-radius: 8px;
  transition: all var(--transition);
}
.dropdown-item:hover { color: #fff; background: rgba(108,194,74,0.1); }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
}
.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: all 0.3s ease;
}

/* Buttons */
.btn-primary {
  background: var(--green);
  color: #0D1B2A;
  font-weight: 700;
  font-size: 0.9rem;
  padding: 0.65rem 1.4rem;
  border-radius: var(--radius-sm);
  text-decoration: none;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.2s ease;
  font-family: inherit;
  letter-spacing: 0.01em;
}
.btn-primary:hover {
  background: var(--green-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(108,194,74,0.35);
}
.btn-primary:active { transform: scale(0.97); }

.btn-outline {
  background: transparent;
  color: #fff;
  font-weight: 600;
  font-size: 0.9rem;
  padding: 0.65rem 1.4rem;
  border-radius: var(--radius-sm);
  text-decoration: none;
  border: 1px solid rgba(255,255,255,0.3);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  transition: all 0.2s ease;
  font-family: inherit;
}
.btn-outline:hover {
  border-color: #fff;
  background: rgba(255,255,255,0.06);
}

.btn-ghost {
  background: transparent;
  color: rgba(255,255,255,0.7);
  font-weight: 500;
  font-size: 0.9rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  text-decoration: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  transition: color var(--transition);
}
.btn-ghost:hover { color: #fff; }

.btn-lg { padding: 0.85rem 1.85rem; font-size: 0.95rem; }
.btn-sm { padding: 0.45rem 1rem; font-size: 0.82rem; }

/* Section typography */
.section-label {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--green);
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}
.section-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 800;
  color: #fff;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 1rem;
}
.section-desc {
  color: var(--text-muted);
  font-size: 1rem;
  line-height: 1.75;
  margin-bottom: 2rem;
}

/* Page Hero (inner pages) */
.page-hero {
  padding: 9rem 0 5rem;
  background: linear-gradient(135deg, #0D1B2A 0%, #15295A 60%, #0D1B2A 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(108,194,74,0.3), transparent);
}
.page-hero-content { max-width: 700px; }
.page-hero h1 {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 900;
  color: #fff;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: 1.25rem;
}
.page-hero h1 span { color: var(--green); }
.page-hero p {
  font-size: 1.1rem;
  color: var(--text-muted);
  line-height: 1.75;
  margin-bottom: 2rem;
}

/* Feature card */
.feature-card {
  background: rgba(21,41,90,0.35);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  transition: all 0.3s ease;
}
.feature-card:hover {
  border-color: var(--border-green);
  transform: translateY(-3px);
  box-shadow: var(--shadow);
}
.feature-icon {
  width: 48px; height: 48px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, rgba(108,194,74,0.15), rgba(108,194,74,0.05));
  border: 1px solid rgba(108,194,74,0.2);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.3rem;
  margin-bottom: 1.25rem;
}
.feature-title {
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 0.6rem;
}
.feature-desc {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.6;
}

/* Footer */
.footer {
  background: #080f1a;
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: 4rem 0 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2.5rem;
  margin-bottom: 3rem;
}
.footer-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin-bottom: 1rem;
  text-decoration: none;
}
.footer-tagline {
  font-size: 0.85rem;
  color: var(--text-dim);
  line-height: 1.6;
  margin-bottom: 1.5rem;
}
.footer-logins { display: flex; flex-direction: column; gap: 0.4rem; }
.footer-login-label { font-size: 0.72rem; font-weight: 600; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.1em; margin-bottom: 0.4rem; }
.footer-login-link { font-size: 0.82rem; color: var(--text-muted); text-decoration: none; transition: color var(--transition); }
.footer-login-link:hover { color: var(--green); }
.footer-col-title { font-size: 0.75rem; font-weight: 700; color: rgba(255,255,255,0.4); text-transform: uppercase; letter-spacing: 0.12em; margin-bottom: 1rem; }
.footer-link { display: block; font-size: 0.875rem; color: var(--text-muted); text-decoration: none; margin-bottom: 0.6rem; transition: color var(--transition); }
.footer-link:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}
.footer-copy { font-size: 0.82rem; color: var(--text-dim); }
.footer-regions { display: flex; gap: 1.5rem; }
.footer-regions span { font-size: 0.78rem; color: var(--text-dim); }

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  background: #1a2535;
  border-top: 1px solid rgba(108,194,74,0.25);
  padding: 1.25rem 2rem;
  z-index: 2000;
  transform: translateY(100%);
  transition: transform 0.4s ease;
  box-shadow: 0 -8px 32px rgba(0,0,0,0.4);
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-content {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
}
.cookie-text { font-size: 0.875rem; color: var(--text-muted); }
.cookie-link { color: var(--green); text-decoration: none; margin-left: 0.4rem; }
.cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; }

/* Utilities */
.text-green { color: var(--green); }
.text-blue { color: var(--blue); }
.text-muted { color: var(--text-muted); }
.mt-1 { margin-top: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mt-3 { margin-top: 1.5rem; }
.mt-4 { margin-top: 2rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mb-2 { margin-bottom: 1rem; }
.mb-3 { margin-bottom: 1.5rem; }
.mb-4 { margin-bottom: 2rem; }

/* Divider */
.divider {
  border: none;
  border-top: 1px solid var(--border);
  margin: 4rem 0;
}

/* Responsive */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: fixed;
    top: 72px; left: 0; right: 0; bottom: 0;
    background: rgba(13,27,42,0.98);
    flex-direction: column;
    align-items: flex-start;
    padding: 1.5rem;
    gap: 0.5rem;
    overflow-y: auto;
  }
  .nav-links.open { display: flex; }
  .hamburger { display: flex; }
  .btn-ghost { display: none; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .footer-regions { flex-wrap: wrap; }
  .container { padding: 0 1.25rem; }
  .dropdown-menu {
    position: static;
    opacity: 1;
    visibility: visible;
    transform: none;
    box-shadow: none;
    border: none;
    background: rgba(255,255,255,0.04);
    margin-left: 0.5rem;
    padding: 0.25rem 0.5rem;
    border-radius: 8px;
  }
