<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Platform Overview — WellStream Platform</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<link rel="stylesheet" href="shared.css">
<style>
/* Benefits section */
.benefits-section { padding: 6rem 0; background: #0D1B2A; }
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1.25rem;
  margin-top: 3rem;
}
.benefit-card {
  background: rgba(21,41,90,0.35);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 14px;
  padding: 1.75rem 1.5rem;
  text-align: center;
  transition: all 0.3s ease;
}
.benefit-card:hover {
  border-color: rgba(108,194,74,0.3);
  transform: translateY(-4px);
  box-shadow: 0 12px 32px rgba(0,0,0,0.25);
}
.benefit-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
  display: block;
}
.benefit-title {
  font-size: 0.95rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 0.6rem;
}
.benefit-desc { font-size: 0.8rem; color: rgba(255,255,255,0.6); line-height: 1.6; }

/* Stats section */
.stats-section {
  padding: 5rem 0;
  background: linear-gradient(135deg, #15295A 0%, #0D1B2A 100%);
  border-top: 1px solid rgba(108,194,74,0.12);
  border-bottom: 1px solid rgba(108,194,74,0.12);
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}
.stat-circle-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
.stat-circle {
  position: relative;
  width: 160px;
  height: 160px;
  margin-bottom: 1.5rem;
}
.stat-circle svg {
  transform: rotate(-90deg);
  width: 160px; height: 160px;
}
.stat-circle .circle-bg {
  fill: none;
  stroke: rgba(255,255,255,0.06);
  stroke-width: 8;
}
.stat-circle .circle-fill {
  fill: none;
  stroke: #6CC24A;
  stroke-width: 8;
  stroke-linecap: round;
  stroke-dasharray: 440;
  stroke-dashoffset: 440;
  transition: stroke-dashoffset 1.5s ease;
}
.stat-circle.animate .circle-fill { stroke-dashoffset: var(--offset); }
.stat-inner {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
}
.stat-value {
  font-size: 2.25rem;
  font-weight: 900;
  color: #fff;
  line-height: 1;
}
.stat-unit { font-size: 1rem; font-weight: 700; color: #6CC24A; }
.stat-label { font-size: 0.9rem; font-weight: 600; color: #fff; margin-bottom: 0.4rem; }
.stat-sublabel { font-size: 0.8rem; color: rgba(255,255,255,0.6); max-width: 200px; }

/* Timeline section */
.timeline-section {
  padding: 6rem 0;
  background: #0D1B2A;
}
.timeline-items { margin-top: 3rem; display: flex; flex-direction: column; gap: 2rem; }
.timeline-item {
  display: grid;
  grid-template-columns: 130px 1fr;
  gap: 2rem;
  align-items: center;
  background: rgba(21,41,90,0.3);
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 14px;
  padding: 2rem;
}
.timeline-duration {
  text-align: center;
}
.timeline-num {
  font-size: 2.5rem;
  font-weight: 900;
  color: #6CC24A;
  line-height: 1;
}
.timeline-unit { font-size: 0.75rem; font-weight: 700; color: rgba(255,255,255,0.5); text-transform: uppercase; letter-spacing: 0.1em; }
.timeline-right { flex: 1; }
.timeline-name { font-size: 1rem; font-weight: 700; color: #fff; margin-bottom: 0.75rem; }
.timeline-bar {
  height: 8px;
  border-radius: 4px;
  background: rgba(255,255,255,0.08);
  overflow: hidden;
}
.timeline-bar-fill {
  height: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, #6CC24A, #00B4D8);
  width: 0;
  transition: width 1.2s ease;
}
.timeline-bar.animate .timeline-bar-fill { width: var(--w); }

/* Accordion */
.accordion-section {
  padding: 6rem 0;
  background: linear-gradient(180deg, #0D1B2A 0%, #111E2E 100%);
}
.accordion-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
  margin-top: 3rem;
}
.accordion-items { display: flex; flex-direction: column; gap: 0; }
.accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.accordion-header {
  width: 100%;
  background: none;
  border: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.4rem 0;
  cursor: pointer;
  font-family: inherit;
  text-align: left;
  gap: 1rem;
}
.accordion-header-text {
  font-size: 1rem;
  font-weight: 700;
  color: rgba(255,255,255,0.8);
  transition: color 0.2s;
}
.accordion-item.open .accordion-header-text { color: #6CC24A; }
.accordion-icon {
  width: 24px; height: 24px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.2);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  color: rgba(255,255,255,0.5);
  font-size: 1rem;
  line-height: 1;
  transition: all 0.3s ease;
}
.accordion-item.open .accordion-icon {
  background: #6CC24A;
  border-color: #6CC24A;
  color: #0D1B2A;
  transform: rotate(45deg);
}
.accordion-body {
  overflow: hidden;
  max-height: 0;
