<script>
// Accordion
const accordionItems = document.querySelectorAll('.accordion-item');
const previewIcon = document.getElementById('previewIcon');
const previewTitle = document.getElementById('previewTitle');
const previewDesc = document.getElementById('previewDesc');

accordionItems.forEach(item => {
  item.querySelector('.accordion-header').addEventListener('click', () => {
    const isOpen = item.classList.contains('open');
    accordionItems.forEach(i => {
      i.classList.remove('open');
      i.querySelector('.accordion-header').setAttribute('aria-expanded', 'false');
    });
    if (!isOpen) {
      item.classList.add('open');
      item.querySelector('.accordion-header').setAttribute('aria-expanded', 'true');
      if (previewIcon) {
        previewIcon.textContent = item.dataset.icon;
        previewTitle.textContent = item.dataset.title;
        previewDesc.textContent = item.dataset.desc;
      }
    }
  });
});

// Stats animation on scroll
const statCircles = document.querySelectorAll('.stat-circle');
const timelineBars = document.querySelectorAll('.timeline-bar');

const animateStats = new IntersectionObserver(entries => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('animate');
      animateStats.unobserve(entry.target);
    }
  });
}, { threshold: 0.3 });

statCircles.forEach(c => {
  const pct = parseInt(c.dataset.percent) / 100;
  const circumference = 2 * Math.PI * 70;
  const offset = circumference * (1 - pct);
  c.querySelector('.circle-fill').style.setProperty('--target-offset', offset);
  c.style.setProperty('--offset', offset);
  animateStats.observe(c);
  // trigger animation via CSS variable on the element
  const observer2 = new IntersectionObserver(([e]) => {
    if (e.isIntersecting) {
      e.target.querySelector('.circle-fill').style.strokeDashoffset = offset;
      observer2.unobserve(e.target);
    }
  }, { threshold: 0.3 });
  observer2.observe(c);
});

timelineBars.forEach(bar => {
  const observer = new IntersectionObserver(([entry]) => {
    if (entry.isIntersecting) {
      bar.classList.add('animate');
      observer.unobserve(bar);
    }
  }, { threshold: 0.3 });
  observer.observe(bar);
});

// Testimonial carousel
const slides = document.getElementById('testimonialSlides');
const dots = document.querySelectorAll('.carousel-dot');
let current = 0;

function goTo(idx) {
  current = idx;
  slides.style.transform = `translateX(-${idx * 100}%)`;
  dots.forEach((d, i) => d.classList.toggle('active', i === idx));
}

dots.forEach(dot => {
  dot.addEventListener('click', () => goTo(parseInt(dot.dataset.idx)));
});

// Auto-rotate
setInterval(() => goTo((current + 1) % 3), 5000);
</script>
