<script>
const form = document.getElementById('demoForm');
const formContent = document.getElementById('formContent');
const formSuccess = document.getElementById('formSuccess');
const submitBtn = document.getElementById('submitBtn');
const btnText = document.getElementById('btnText');
const btnSpinner = document.getElementById('btnSpinner');

// Validation rules
const requiredFields = [
  { id: 'firstName', errId: 'err-firstName', validate: v => v.trim().length > 0 },
  { id: 'lastName', errId: 'err-lastName', validate: v => v.trim().length > 0 },
  { id: 'email', errId: 'err-email', validate: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()) },
  { id: 'company', errId: 'err-company', validate: v => v.trim().length > 0 },
  { id: 'jobTitle', errId: 'err-jobTitle', validate: v => v.trim().length > 0 },
  { id: 'country', errId: 'err-country', validate: v => v !== '' },
];

function validateField(field) {
  const el = document.getElementById(field.id);
  const err = document.getElementById(field.errId);
  const valid = field.validate(el.value);
  el.classList.toggle('error', !valid);
  err.classList.toggle('visible', !valid);
  return valid;
}

// Live validation on blur
requiredFields.forEach(field => {
  const el = document.getElementById(field.id);
  el.addEventListener('blur', () => validateField(field));
  el.addEventListener('input', () => {
    if (el.classList.contains('error')) validateField(field);
  });
});

form.addEventListener('submit', e => {
  e.preventDefault();
  let allValid = requiredFields.every(validateField);
  if (!allValid) {
    const firstError = document.querySelector('.form-input.error, .form-select.error');
    if (firstError) firstError.focus();
    return;
  }

  // Simulate submission
  submitBtn.disabled = true;
  btnText.textContent = 'Submitting...';
  btnSpinner.style.display = 'inline';

  setTimeout(() => {
    formContent.style.display = 'none';
    formSuccess.classList.add('visible');
    window.scrollTo({ top: document.querySelector('.demo-form-section').offsetTop - 100, behavior: 'smooth' });
  }, 1200);
});
</script>
